compose_template:
services:
  vllm-qwen38fn1:
    image: ${VLLM_IMAGE:-registry.cn-shanghai.aliyuncs.com/aixn-public/qwen38-flash-next:v1.2.0}
    container_name: ${TASK_NAME}-qwen38fn1
    healthcheck:
      test: ["CMD", "python3", "-c", "import urllib.request,sys; sys.exit(0 if urllib.request.urlopen('http://127.0.0.1:${PORT:-8888}/health', timeout=5).status == 200 else 1)"]
      interval: 30s
      timeout: 5s
      retries: 3
      start_period: 900s
    pull_policy: if_not_present
    entrypoint: []
    network_mode: host
    ipc: host
    shm_size: "32gb"
    ulimits:
      memlock: -1
      stack: 67108864
    gpus: all
    volumes:
      # 宿主 HF 缓存挂到 /hf（HF_HOME=/hf，模型由管理平台分发到节点缓存，离线解析）
      - ${HF_CACHE:-${HOME}/.cache/huggingface}:/hf
      # PLE 打包表所在宿主目录（首启前须构建好，容器内按 repo id 解析，见 README）
      - ${VLLM_CACHE:-${HOME}/.cache/vllm}:/root/.cache/vllm
    environment:
      HF_HOME: /hf
      HF_HUB_OFFLINE: "1"  # 模型由管理平台分发到节点缓存，固定离线加载
      HF_HUB_DISABLE_XET: "${HF_HUB_DISABLE_XET:-1}"
      HF_TOKEN: "${HF_TOKEN:-}"
      TRANSFORMERS_OFFLINE: "1"
      # PLE 表 CPU 离载（本配方成立的核心开关；TP=1 下勿关——99 GB 权重过 UVM 会挂主机）
      VLLM_PLE_CPU_OFFLOAD: "1"
      VLLM_PLE_OFFLOAD_STEP_TIMEOUT: "${PLE_STEP_TIMEOUT:-300}"
    command:
      - bash
      - -lc
      - >
        set -e;
        PLE_ORG=${QWN38_MODEL:-Mia-AiLab/Qwen3.8-Flash-Next-NVFP4};
        PLE_NAME=$(printf %s "$PLE_ORG" | sed 's|/|--|g');
        PLE_DIR="/root/.cache/vllm/ple_cache/$PLE_NAME";
        if ! ls "$PLE_DIR"/*.packed_u8 >/dev/null 2>&1; then
          echo "PLE packed table missing: host ~/.cache/vllm/ple_cache/$PLE_NAME (build it once, see README)"; exit 1;
        fi;
        VLLM_ARGS=();
        CTX=${MAX_MODEL_LEN:-262144};
        if [ "${YARN:-0}" = "1" ]; then
          CTX=${YARN_MAX_MODEL_LEN:-524288};
          VLLM_ARGS+=(--hf-overrides);
          VLLM_ARGS+=('{"text_config":{"rope_parameters":{"rope_type":"yarn","factor":2.0,"original_max_position_embeddings":262144}}}');
        elif [ "$CTX" -gt 262144 ]; then
          echo "MAX_MODEL_LEN > 262144 需 YARN=1（YaRN rope）；请下调或设 YARN=1"; exit 1;
        fi;
        if [ "${MTP:-3}" != "0" ]; then
          CG_SIZES=[];
          if [ "${CUDAGRAPH_CAPTURE_SIZES:-auto}" = "auto" ]; then
            CG_SIZES="$(python3 -c "print(','.join(str((1+${MTP:-3})*s) for s in range(1,${MAX_NUM_SEQS:-4}+1)))")";
          else
            CG_SIZES=${CUDAGRAPH_CAPTURE_SIZES};
          fi;
          VLLM_ARGS+=(--speculative-config);
          VLLM_ARGS+=("{\"method\":\"mtp\",\"num_speculative_tokens\":${MTP:-3},\"use_local_argmax_reduction\":$( [ -n "${MTP_DRAFT_VOCAB:-}" ] && echo true || echo false),\"model\":\"${QWN38_MODEL:-Mia-AiLab/Qwen3.8-Flash-Next-NVFP4}\"}");
          VLLM_ARGS+=(--compilation-config);
          VLLM_ARGS+=("{\"mode\":0,\"cudagraph_mode\":\"${CUDAGRAPH_MODE:-FULL_DECODE_ONLY}\",\"cudagraph_capture_sizes\":[${CG_SIZES}]}");
        fi;
        exec vllm serve "$PLE_ORG"
        --served-model-name ${SERVED_MODEL_NAME:-qwen3.8-flash-next}
        --tensor-parallel-size 1
        --gpu-memory-utilization ${GPU_MEMORY_UTILIZATION:-0.78}
        --max-num-seqs ${MAX_NUM_SEQS:-4}
        --max-num-batched-tokens ${MAX_NUM_BATCHED_TOKENS:-2048}
        --max-model-len $CTX
        --kv-cache-dtype ${KV_CACHE_DTYPE:-fp8}
        "${VLLM_ARGS[@]}"
        --load-format safetensors
        --safetensors-load-strategy lazy
        --enable-chunked-prefill
        --reasoning-parser qwen3
        --enable-auto-tool-choice
        --tool-call-parser qwen3_coder
        --distributed-executor-backend mp
        --host 0.0.0.0
        --port ${PORT:-8888}
